from pathlib import Path
import json, re, html
OUT=Path(__file__).resolve().parent
T=[]
def table(name,group,description,columns,rules=()):
    T.append(dict(name=name,group=group,description=description,columns=columns,rules=list(rules)))
def c(name,typ='uuid',flags='',desc=''):
    return dict(name=name,type=typ,flags=flags,description=desc)
def ident(): return c('id','uuid','PRIMARY KEY DEFAULT gen_random_uuid()','Identificador interno')
def ref(name,target,optional=False): return c(name,'uuid',('' if optional else 'NOT NULL ')+f'REFERENCES {target}(id)',f'Referencia a {target}')
def txt(name,optional=False,desc=''): return c(name,'text','' if optional else 'NOT NULL',desc)
def stamp(name='created_at',optional=False): return c(name,'timestamptz','' if optional else 'NOT NULL DEFAULT now()')
def farm(): return ref('farm_id','farms')
def samefarm(name,target): return f'FOREIGN KEY ({name},farm_id) REFERENCES {target}(id,farm_id)'
def period(): return [stamp('valid_from'),stamp('valid_to',True)]
def periodrules(key): return ["CHECK(valid_to IS NULL OR valid_to>valid_from)",f"EXCLUDE USING gist ({key} WITH =, tstzrange(valid_from,valid_to,'[)') WITH &&)"]

